8	/**
9	 * Represent a rectangular grid of field positions.
10	 * Each position is able to store a single creature.
11	 *
12	 * @version 2022/03/02
13	 */
14	public class Field
15	{
16	    // A random number generator for providing random locations.
17	    private static final Random rand = Randomizer.getRandom();
18	    
19	    // The depth and width of the field.
20	    private int depth, width;
21	    // Storage for the creatures.
22	    private Object[][] field;
23	
24	    /**
25	     * Represent a field of the given dimensions.
26	     * @param depth The depth of the field.
27	     * @param width The width of the field.
28	     */
29	    public Field(int depth, int width)
30	    {
31	        this.depth = depth;
32	        this.width = width;
33	        field = new Object[depth][width];
34	    }
35	    
36	    /**
37	     * Empty the field.
38	     */
39	    public void clear()
40	    {
41	        for(int row = 0; row < depth; row++) {
42	            for(int col = 0; col < width; col++) {
43	                field[row][col] = null;
44	            }
45	        }
46	    }
47	    
48	    /**
49	     * Clear the given location.
50	     * @param location The location to clear.
51	     */
52	    public void clear(Location location)
53	    {
54	        field[location.getRow()][location.getCol()] = null;
55	    }
56	    
57	    /**
58	     * Place a creature at the given location.
59	     * If there is already a creature at the location it will
60	     * be lost.
61	     * @param creature The creature to be placed.
62	     * @param row Row coordinate of the location.
63	     * @param col Column coordinate of the location.
64	     */
65	    public void place(Object creature, int row, int col)
66	    {
67	        place(creature, new Location(row, col));
68	    }
69	    
70	    /**
71	     * Place an creature at the given location.
72	     * If there is already an creature at the location it will
73	     * be lost.
74	     * @param creature The creature to be placed.
75	     * @param location Where to place the creature.
76	     */
77	    public void place(Object creature, Location location)
78	    {
79	        field[location.getRow()][location.getCol()] = creature;
80	    }
81	    
82	    /**
83	     * Return the creature at the given location, if any.
84	     * @param location Where in the field.
85	     * @return The creature at the given location, or null if there is none.
86	     */
87	    public Object getObjectAt(Location location)
88	    {
89	        return getObjectAt(location.getRow(), location.getCol());
90	    }
91	    
92	    /**
93	     * Return the creature at the given location, if any.
94	     * @param row The desired row.
95	     * @param col The desired column.
96	     * @return The creature at the given location, or null if there is none.
97	     */
98	    public Object getObjectAt(int row, int col)
99	    {
100	        return field[row][col];
101	    }
102	    
103	    /**
104	     * Generate a random location that is adjacent to the
105	     * given location, or is the same location.
106	     * The returned location will be within the valid bounds
107	     * of the field.
108	     * @param location The location from which to generate an adjacency.
109	     * @return A valid location within the grid area.
110	     */
111	    public Location randomAdjacentLocation(Location location)
112	    {
113	        List<Location> adjacent = adjacentLocations(location, 1);
114	        return adjacent.get(0);
115	    }
116	    
117	    /**
118	     * Get a shuffled list of the free adjacent locations.
119	     * @param location Get locations adjacent to this.
120	     * @return A list of free adjacent locations.
121	     */
122	    public List<Location> getFreeAdjacentLocations(Location location)
123	    {
124	        List<Location> free = new LinkedList<>();
125	        List<Location> adjacent = adjacentLocations(location, 1);
126	        for(Location next : adjacent) {
127	            if(getObjectAt(next) == null) {
128	                free.add(next);
129	            }
130	        }
131	        return free;
132	    }
133	    
134	    /**
135	     * Try to find a free location that is adjacent to the
136	     * given location. If there is none, return null.
137	     * The returned location will be within the valid bounds
138	     * of the field.
139	     * @param location The location from which to generate an adjacency.
140	     * @return A valid location within the grid area.
141	     */
142	    public Location freeAdjacentLocation(Location location)
143	    {
144	        // The available free ones.
145	         List<Location> free = getFreeAdjacentLocations(location);
146	        if(free.size() > 0) {
147	            return free.get(0);
148	        }
149	        else {
150	            return null;
151	        }
152	    }
153	
154	   
155	    /**
156	     * Return a shuffled list of locations adjacent to the given one.
157	     * The list will INCLUDE the location itself.
158	     * All locations will lie within the grid.
159	     * 
160	     * @param location The location from which to generate adjacencies.
161	     * @return A list of locations adjacent to that given.
162	     */
163	    public List<Location> adjacentLocationsIncludingSelf(Location location, int adjacentDistance)
164	    {
165	        assert location != null : "Null location passed to adjacentLocations";
166	        // The list of locations to be returned.
167	        List<Location> locations = new LinkedList<>();
168	        if(location != null) {
169	            int row = location.getRow();
170	            int col = location.getCol();
171	            for(int roffset = -adjacentDistance; roffset <= adjacentDistance; roffset++) {
172	                int nextRow = row + roffset;
173	                if(nextRow >= 0 && nextRow < depth) {
174	                    for(int coffset = -adjacentDistance; coffset <= adjacentDistance; coffset++) {
175	                        int nextCol = col + coffset;
176	                        // Exclude invalid locations and the original location.
177	                        if(nextCol >= 0 && nextCol < width) {
178	                            locations.add(new Location(nextRow, nextCol));
179	                        }
180	                    }
181	                }
182	            }
183	            
184	            // Shuffle the list. Several other methods rely on the list
185	            // being in a random order.
186	            Collections.shuffle(locations, rand);
187	        }
188	        return locations;
189	    }
190	    
191	    /**
192	     * Return a shuffled list of locations adjacent to the given one.
193	     * The list will not include the location itself.
194	     * All locations will lie within the grid.
195	     * @param location The location from which to generate adjacencies.
196	     * @return A list of locations adjacent to that given.
197	     */
198	    public List<Location> adjacentLocations(Location location, int adjacentDistance)
199	    {
