4	/**
5	 * This class collects and provides some statistical data on the state 
6	 * of a field. It is flexible: it will create and maintain a counter 
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 2022/03/02
10	 */
11	public class FieldStats
12	{
13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
14	    private HashMap<Class, Counter> counters;
15	    // Whether the counters are currently up to date.
16	    private boolean countsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        // Set up a collection for counters for each type of animal that
24	        // we might find
25	        counters = new HashMap<>();
26	        countsValid = true;
27	    }
28	
29	    /**
30	     * Get details of what is in the field.
31	     * @return A string describing what is in the field.
32	     */
33	    public String getPopulationDetails(Field field)
34	    {
35	        StringBuffer buffer = new StringBuffer();
36	        if(!countsValid) {
37	            generateCounts(field);
38	        }
39	        for(Class key : counters.keySet()) {
40	            Counter info = counters.get(key);
41	            buffer.append(info.getName());
42	            buffer.append(": ");
43	            buffer.append(info.getCount());
44	            buffer.append(' ');
45	        }
46	        return buffer.toString();
47	    }
48	    
49	    /**
50	     * Invalidate the current set of statistics; reset all 
51	     * counts to zero.
52	     */
53	    public void reset()
54	    {
55	        countsValid = false;
56	        for(Class key : counters.keySet()) {
57	            Counter count = counters.get(key);
58	            count.reset();
59	        }
60	    }
61	    
62	    
63	
64	    /**
65	     * Increment the count for one class of animal.
66	     * @param animalClass The class of animal to increment.
67	     */
68	    public void incrementCount(Class animalClass)
69	    {
70	        Counter count = counters.get(animalClass);
71	        if(count == null) {
72	            // We do not have a counter for this species yet.
73	            // Create one.
74	            count = new Counter(animalClass.getName());
75	            counters.put(animalClass, count);
76	        }
77	        count.increment();
78	    }
79	
80	    /**
81	     * Indicate that an animal count has been completed.
82	     */
83	    public void countFinished()
84	    {
85	        countsValid = true;
86	    }
87	
88	    /**
89	     * Determine whether the simulation is still viable.
90	     * I.e., should it continue to run.
91	     * @return true If there is more than one species alive.
92	     */
93	    public boolean isViable(Field field)
94	    {
95	        // How many counts are non-zero.
96	        int nonZero = 0;
97	        if(!countsValid) {
98	            generateCounts(field);
99	        }
100	        for(Class key : counters.keySet()) {
101	            Counter info = counters.get(key);
102	            if(info.getCount() > 0) {
103	                nonZero++;
104	            }
105	        }
106	        return nonZero > 1;
107	    }
108	    
109	    /**
110	     * Generate counts of the number of foxes and rabbits.
111	     * These are not kept up to date as foxes and rabbits
112	     * are placed in the field, but only when a rrandomAdjacentLocationequest
113	     * is made for the information.
114	     * @param field The field to generate the stats for.
115	     */
116	    private void generateCounts(Field field)
117	    {
118	        reset();
119	        for(int row = 0; row < field.getDepth(); row++) {
120	            for(int col = 0; col < field.getWidth(); col++) {
121	                Object animal = field.getObjectAt(row, col);
122	                if(animal != null) {
123	                    incrementCount(animal.getClass());
124	                }
125	            }
126	        }
127	        countsValid = true;
128	    }
129	}
